interface User {
  id: number;
  name: string;
  email: string;
}

// This is identical to: type UserKeys = "id" | "name" | "email"
type UserKeys = keyof User;

// Powerful Generic use case: T is the object, K is constrained to be a valid key of T
function getProperty<T, K extends keyof T>(obj: T, key: K) {
  return obj[key];
}

const person: User = { id: 1, name: "Alice", email: "a@a.com" };

// Valid! Returns a string.
const val = getProperty(person, "name"); 

// ERROR: Argument of type '"age"' is not assignable to parameter of type 'keyof User'.
